399	// allocates one workspace that fits every OptId. Unused by AdamW/Lion/… (their
400	// P3 never touches this region), so adding it leaves those cells byte-identical.
401	__host__ __device__ __forceinline__ int64_t dec_tc_opt_reduce_floats(int nCTA) {
402	    return (int64_t)2 * nCTA + 1;            // [r slots | s slots | reduced d]
