39	// One persistent set of barrier/queue counters + the TC workspace, cached per
40	// device (the kernel zeroes the barrier per launch; the workspace is sized for
41	// the TC layout, NOT the scalar 223 MB partials). Re-created if a larger B
42	// requires a larger workspace.
43	struct TcScratch {
44	    torch::Tensor g_next;       // int [1]
45	    torch::Tensor g_arrived;    // int [1]
46	    torch::Tensor g_generation; // int [1]
47	    torch::Tensor workspace;    // float [dec_tc_workspace_floats(T,B,nCTA)]
48	    int n_ctas = 0;
49	    int64_t ws_floats = 0;
50	};
